// lib/logoAssets.js
// Logo SIMFONI & BPS di-encode base64 langsung di sini (bukan dibaca dari
// public/ pakai fs saat runtime) -- fs.readFileSync ke folder public/ kadang
// gagal di lingkungan serverless kayak Vercel (public/ biasanya dianggap
// buat CDN statis doang, bukan buat dibaca server-side), jadi cara ini lebih
// aman/pasti jalan di mana pun di-deploy. Sumber asli file gambarnya tetap
// ada di public/images/ (dipakai website), ini cuma salinan buat PDF.
const LOGO_SIMFONI_BASE64 = "";
const LOGO_BPS_BASE64 = "";

const LOGO_SIMFONI = Buffer.from(LOGO_SIMFONI_BASE64, "base64");
const LOGO_BPS = Buffer.from(LOGO_BPS_BASE64, "base64");
const LOGO_SIMFONI_RATIO = 1050 / 600; // lebar/tinggi asli filenya
const LOGO_BPS_RATIO = 1050 / 430;

module.exports = { LOGO_SIMFONI, LOGO_BPS, LOGO_SIMFONI_RATIO, LOGO_BPS_RATIO };